from functools import lru_cache
import base64, hashlib, hmac, json, os, time
from fastapi import Depends, HTTPException
from fastapi.security import HTTPAuthorizationCredentials, HTTPBearer

bearer = HTTPBearer(auto_error=False)


def secret():
    value = os.getenv("AUTH_SECRET", "")
    if len(value) < 32:
        raise HTTPException(503, "Configure AUTH_SECRET com pelo menos 32 caracteres")
    return value.encode()


def users():
    # Store only salted PBKDF2 digests generated by scripts/init_demo.py.
    from pathlib import Path

    path = Path(os.getenv("DEMO_USERS_FILE", "app/data/demo_users.json"))
    if not path.exists():
        raise HTTPException(503, "Execute scripts/init_demo.py")
    return json.loads(path.read_text(encoding="utf-8"))


def password_hash(password, salt):
    return hashlib.pbkdf2_hmac(
        "sha256", password.encode(), bytes.fromhex(salt), 200000
    ).hex()


def login(username, password):
    if os.getenv("AUTH_MODE", "demo") != "demo":
        raise HTTPException(403, "Login local desabilitado; use seu provedor OIDC")
    u = users().get(username)
    salt = u["salt"] if u else "00" * 16
    digest = password_hash(password, salt)
    if not u or not hmac.compare_digest(digest, u["hash"]):
        raise HTTPException(401, "Credenciais inválidas")
    body = base64.urlsafe_b64encode(
        json.dumps(
            {"sub": username, "role": u["role"], "exp": int(time.time()) + 3600}
        ).encode()
    ).decode()
    sig = hmac.new(secret(), body.encode(), hashlib.sha256).hexdigest()
    return {"access_token": body + "." + sig, "token_type": "bearer", "role": u["role"]}


def identity(credentials: HTTPAuthorizationCredentials = Depends(bearer)):
    if not credentials:
        raise HTTPException(401, "Autenticação obrigatória")
    mode = os.getenv("AUTH_MODE", "demo")
    if mode not in ("demo", "oidc"):
        raise HTTPException(503, "AUTH_MODE inválido")
    if mode == "oidc":
        return oidc_identity(credentials.credentials)
    try:
        body, sig = credentials.credentials.split(".")
        if not hmac.compare_digest(
            hmac.new(secret(), body.encode(), hashlib.sha256).hexdigest(), sig
        ):
            raise ValueError()
        claim = json.loads(base64.urlsafe_b64decode(body))
        if claim["exp"] <= time.time() or claim["role"] not in (
            "customer",
            "operator",
            "admin",
        ):
            raise ValueError()
        current = users().get(claim["sub"])
        if not current or current["role"] != claim["role"]:
            raise ValueError()
        return claim
    except (ValueError, KeyError, TypeError):
        raise HTTPException(401, "Token inválido ou expirado")


def customer(who=Depends(identity)):
    if who["role"] != "customer":
        raise HTTPException(403, "Somente cliente")
    return who


@lru_cache(maxsize=4)
def jwks_client(url):
    import jwt

    return jwt.PyJWKClient(url, cache_keys=True, lifespan=300, timeout=5)


def oidc_identity(token):
    """Validate issuer, audience, expiry and server-controlled customer mapping."""
    import jwt

    issuer = os.getenv("OIDC_ISSUER", "")
    audience = os.getenv("OIDC_AUDIENCE", "")
    url = os.getenv("OIDC_JWKS_URL", "")
    if not issuer or not audience or not url.startswith("https://"):
        raise HTTPException(503, "Configure OIDC issuer, audience and HTTPS JWKS")
    try:
        key = jwks_client(url).get_signing_key_from_jwt(token).key
        claim = jwt.decode(
            token,
            key,
            algorithms=["RS256"],
            audience=audience,
            issuer=issuer,
            options={"require": ["exp", "iat", "sub", "iss", "aud"]},
        )
        # IdP subject -> application customer id is maintained by the server.
        # Never trust a model, payload user_id or arbitrary JWT role claim.
        from pathlib import Path

        mapping = json.loads(
            Path(
                os.getenv("OIDC_IDENTITIES_FILE", "app/data/oidc_identities.json")
            ).read_text()
        )
        bound = mapping.get(claim["sub"])
        if not bound or bound.get("role") not in ("customer", "operator", "admin"):
            raise HTTPException(403, "Identidade não provisionada")
        return {"sub": bound["user_id"], "role": bound["role"], "exp": claim["exp"]}
    except jwt.PyJWTError:
        raise HTTPException(401, "Token OIDC inválido")
    except (OSError, ValueError, TypeError, KeyError):
        raise HTTPException(503, "Mapeamento OIDC indisponível")
